entries[52716] = { ["name"] = "Zwielichtfeuerlanze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand\n1 - 3 Schaden Tempo 3.00\n(0.67 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\nBenötigt Stufe 75\n\"Die Klinge ist aus reinem Feuer geschmiedet, doch der Griff aus Drachenhaut fühlt sich noch immer kühl an.\"" }
