entries[52733] = { ["name"] = "Formel: Waffe - Machtstrom", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (525)\nBenutzen: Lehrt Euch, Waffen dauerhaft zu verzaubern, sodass beim Wirken von Heil- oder Schadenszaubern gelegentlich die Intelligenz erhöht wird. Erfordert einen Gegenstand der Stufe 300 oder höher.\nEine Waffe dauerhaft verzaubern, sodass manchmal Eure Intelligenz 12 Sek. lang um 500 erhöht wird, wenn Ihr Zauberschaden verursacht oder Heilzauber wirkt. Erfordert einen Gegenstand der Stufe 300 oder höher." }
entries[52734] = { ["name"] = "Bruchstück", ["text"] = "Questgegenstand\n\"Dieses Bruchstück sieht aus, als sei es Teil eines Dreizacks gewesen.\"" }
entries[52735] = { ["name"] = "Formel: Waffe - Windwandler", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (525)\nBenutzen: Lehrt Euch, Waffen dauerhaft zu verzaubern, sodass sie Ausweichwertung und Bewegungstempo gelegentlich bei Nahkampfangriffen erhöhen. Erfordert einen Gegenstand der Stufe 300 oder höher.\nEine Waffe dauerhaft verzaubern, sodass manchmal 10 Sek. lang Eure Ausweichwertung um 600 und Euer Bewegungstempo um 15% erhöht wird, wenn Ihr im Nahkampf zuschlagt. Diese Verzauberung ist mit passiven Erhöhungen des Bewegungstempos stapelbar. Erfordert einen Gegenstand der Stufe 300 oder höher." }
entries[52736] = { ["name"] = "Formel: Waffe - Erdrutsch", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (525)\nBenutzen: Lehrt Euch, Waffen dauerhaft zu verzaubern, sodass die Angriffskraft gelegentlich bei Nahkampfangriffen erhöht wird. Erfordert einen Gegenstand der Stufe 300 oder höher.\nEine Waffe dauerhaft verzaubern, sodass manchmal Eure Angriffskraft 12 Sek. lang um 1000 erhöht wird, wenn Ihr im Nahkampf zuschlagt. Erfordert einen Gegenstand der Stufe 300 oder höher." }
